import React, { useState, useEffect } from 'react';
import '../styles/BannerSection.css';

const BannerSection = () => {
    const [currentSlide, setCurrentSlide] = useState(0);
    const slides = [
        { id: 1, img: `${process.env.PUBLIC_URL}/imgg/Акція-крісло.png` },
        { id: 2, img: `${process.env.PUBLIC_URL}/imgg/Group 561.png` },
        { id: 3, img: `${process.env.PUBLIC_URL}/imgg/Group 560.png` }
    ];

    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentSlide((prev) => (prev + 1) % slides.length);
        }, 10000); // Смена слайда каждые 10 секунд
        return () => clearInterval(interval);
    }, [slides.length]);

    const goToSlide = (index) => {
        setCurrentSlide(index);
    };

    return (
        <section className="banner-section">
            <div className="banner-container">
                <div
                    className="banner-slides"
                    style={{ transform: `translateX(-${currentSlide * 100}%)` }}
                >
                    {slides.map(slide => (
                        <div key={slide.id} className="banner-slide">
                            <img src={slide.img} alt={`Баннер ${slide.id}`} />
                        </div>
                    ))}
                </div>
            </div>
            <div className="banner-indicators">
                {slides.map((_, index) => (
                    <div
                        key={index}
                        className={`indicator ${index === currentSlide ? 'active' : ''}`}
                        onClick={() => goToSlide(index)}
                    ></div>
                ))}
            </div>
        </section>
    );
};

export default BannerSection;
